using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {partial class MainForm {
string ReceiptHistoryText(D order){var lines=J.Rows(order,"receiptReturns").Select(e=>J.Text(e,"at")+" / "+J.Text(e,"by")+" / "+J.Text(e,"kind")+" / 수량 "+J.Num(e,"qty")+"\r\n"+J.Text(e,"reason"));return "발주: "+J.Text(order,"name")+"\r\n원입고 "+J.Num(order,"qty")+" / 누적 정정·반품 "+J.Num(order,"returnedQty")+"\r\n재고만 반영하며 환불·지급금은 별도 장부로 관리합니다.\r\n\r\n"+(J.Rows(order,"receiptReturns").Count==0?"처리 이력이 없습니다.":String.Join("\r\n\r\n",lines));}
void ReceiptReturnHistory(){if(!Can("orders.read"))return;D row=Selected();if(row==null){MessageBox.Show("발주를 선택하세요.");return;}var view=new Form{Text="입고 정정 · 반품 이력",Width=780,Height=620};Style.Form(view);view.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=ReceiptHistoryText(row)});OpenWorkspace(view);}
void ReturnReceipt(){if(!Can("orders.write")||!Can("materials.write")){MessageBox.Show("발주·자재 편집 권한이 필요합니다.");return;}D row=Selected();if(row==null||!J.Bool(row,"received")){MessageBox.Show("입고 반영된 발주를 선택하세요.");return;}decimal remaining=Math.Max(0,J.Num(row,"qty")-J.Num(row,"returnedQty"));if(remaining<=0){ReceiptReturnHistory();return;}string id=J.Text(row,"id"),requestId=Guid.NewGuid().ToString();var fields=new[]{new Field("kind","처리 종류","select","공급처반품,입고정정"),new Field("qty","차감 수량 (잔여 "+remaining+")","number"),new Field("reason","사유 (필수)\r\n재고만 반영합니다.\r\n환불은 장부에 별도 기록","note")};var data=J.Row("kind","공급처반품","qty",remaining,"reason","");OpenWorkspace(new EditForm("입고 정정 · 공급처 반품",data,fields,J.Clone(state),value=>{if(J.Num(value,"qty")<=0||J.Num(value,"qty")>remaining){MessageBox.Show("처리 가능한 수량을 입력하세요.");return false;}string reason=J.Text(value,"reason").Trim();if(reason.Length==0||reason.Length>1000){MessageBox.Show("사유를 1~1,000자로 입력하세요.");return false;}try{D result=b.Call("returnReceipt",J.Row("id",id,"qty",J.Num(value,"qty"),"kind",J.Text(value,"kind"),"reason",reason,"requestId",requestId,"version",version));LoadState();ShowPage("orders");MessageBox.Show(J.Text(result,"notice","재고 처리 이력을 저장했습니다."));return true;}catch(Exception ex){MessageBox.Show(ex.Message,"처리하지 못했습니다");return false;}}));}
}}
